#include "s61_binary_deeper_quartic_field_20261101.hpp"
#include <chrono>
Rat denominator(const Row&row){Rat d,g,q;fmpq_mpoly_one(d.n,ctx);for(auto&[j,v]:row){assert(fmpq_mpoly_gcd(g.n,d.n,v.d,ctx));assert(fmpq_mpoly_divides(q.n,v.d,g.n,ctx));fmpq_mpoly_mul(g.n,d.n,q.n,ctx);fmpq_mpoly_swap(g.n,d.n,ctx);}return d;}
Row clear(const Row&row){Rat d=denominator(row),q;Row out;for(auto&[j,c]:row){assert(fmpq_mpoly_divides(q.n,d.n,c.d,ctx));fmpq_mpoly_mul(out[j].n,q.n,c.n,ctx);}return out;}
int main(int argc,char**argv){assert(argc==3);fmpq_mpoly_ctx_init(ctx,2,ORD_LEX);{ifstream in(argv[1]),dual(argv[2]);int nr,nc;in>>nr>>nc;vector<Row>Q(49);for(int i=0;i<49;i++){int n;in>>n;for(int k=0;k<n;k++){int j;in>>j;readpoly(in,Q[i][j].n);readpoly(in,Q[i][j].d);}Q[i]=clear(Q[i]);}int nd;dual>>nd>>nc;assert(nd==2);auto start=chrono::steady_clock::now();for(int i=0;i<2;i++){int id,n;dual>>id>>n;Row lambda;for(int k=0;k<n;k++){int j;dual>>j;readpoly(dual,lambda[j].n);readpoly(dual,lambda[j].d);}lambda=clear(lambda);for(int r=0;r<49;r++){Rat sum,product;for(auto&[j,c]:Q[r]){auto it=lambda.find(j);if(it==lambda.end())continue;fmpq_mpoly_mul(product.n,c.n,it->second.n,ctx);fmpq_mpoly_add(sum.n,sum.n,product.n,ctx);}assert(sum.zero());}cerr<<"ANNIHILATION "<<id<<" all49 PASS "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<'\n';}}fmpq_mpoly_ctx_clear(ctx);flint_cleanup();}
